# Copyright (c) HashiCorp, Inc.
# SPDX-License-Identifier: MPL-2.0

variable "project" {
  default = "openbao-helm-dev-246514"

  description = <<EOF
Google Cloud Project to launch resources in. This project must have GKE
enabled and billing activated. We can't use the GOOGLE_PROJECT environment
variable since we need to access the project for other uses.
EOF
}

variable "zone" {
  default     = "us-central1-a"
  description = "The zone to launch all the GKE nodes in."
}

variable "init_cli" {
  default     = true
  description = "Whether to init kubectl or not."
}

variable "gcp_service_account" {
  default = "vault-terraform-helm-test"

  description = <<EOF
Service account used on the nodes to manage/use the API, specifically needed
for using auto-unseal
EOF
}

# Copyright (c) HashiCorp, Inc.
# SPDX-License-Identifier: MPL-2.0

provider "google" {
  project = "${var.project}"
}

resource "random_id" "suffix" {
  byte_length = 4
}

data "google_container_engine_versions" "main" {
  location = "${var.zone}"
  version_prefix = "1.19."
}

data "google_service_account" "gcpapi" {
  account_id = "${var.gcp_service_account}"
}

resource "google_container_cluster" "cluster" {
  name               = "openbao-helm-dev-${random_id.suffix.dec}"
  project            = "${var.project}"
  enable_legacy_abac = true
  initial_node_count = 3
  location           = "${var.zone}"
  min_master_version = "${data.google_container_engine_versions.main.latest_master_version}"
  node_version       = "${data.google_container_engine_versions.main.latest_node_version}"

  node_config {
    #service account for nodes to use
    oauth_scopes = [
      "https://www.googleapis.com/auth/cloud-platform",
      "https://www.googleapis.com/auth/compute",
      "https://www.googleapis.com/auth/devstorage.read_write",
      "https://www.googleapis.com/auth/logging.write",
      "https://www.googleapis.com/auth/monitoring",
      "https://www.googleapis.com/auth/service.management.readonly",
      "https://www.googleapis.com/auth/servicecontrol",
      "https://www.googleapis.com/auth/trace.append",
    ]

    service_account = "${data.google_service_account.gcpapi.email}"
  }
}

resource "null_resource" "kubectl" {
  count = "${var.init_cli ? 1 : 0 }"

  triggers = {
    cluster = "${google_container_cluster.cluster.id}"
  }

  # On creation, we want to setup the kubectl credentials. The easiest way
  # to do this is to shell out to gcloud.
  provisioner "local-exec" {
    command = "gcloud container clusters get-credentials --zone=${var.zone} ${google_container_cluster.cluster.name}"
  }

  # On destroy we want to try to clean up the kubectl credentials. This
  # might fail if the credentials are already cleaned up or something so we
  # want this to continue on failure. Generally, this works just fine since
  # it only operates on local data.
  provisioner "local-exec" {
    when       = "destroy"
    on_failure = "continue"
    command    = "kubectl config get-clusters | grep ${google_container_cluster.cluster.name} | xargs -n1 kubectl config delete-cluster"
  }

  provisioner "local-exec" {
    when       = "destroy"
    on_failure = "continue"
    command    = "kubectl config get-contexts | grep ${google_container_cluster.cluster.name} | xargs -n1 kubectl config delete-context"
  }
}

#!/usr/bin/env bats

load _helpers

@test "prometheus/ServiceMonitor-server: assertDisabled by default" {
  cd `chart_dir`
  local actual=$( (helm template \
    --show-only templates/prometheus-servicemonitor.yaml \
    . || echo "---") | tee /dev/stderr |
    yq 'length > 0' | tee /dev/stderr)
  [ "${actual}" = "false" ]
}

@test "prometheus/ServiceMonitor-server: assertEnabled global" {
  cd `chart_dir`
  local actual=$( (helm template \
    --show-only templates/prometheus-servicemonitor.yaml \
    --set 'serverTelemetry.serviceMonitor.enabled=false' \
    --set 'global.serverTelemetry.prometheusOperator=true' \
    . || echo "---") | tee /dev/stderr |
    yq 'length > 0' | tee /dev/stderr)
  [ "${actual}" = "true" ]
}

@test "prometheus/ServiceMonitor-server: assertEnabled" {
  cd `chart_dir`
  local actual=$( (helm template \
    --show-only templates/prometheus-servicemonitor.yaml \
    --set 'serverTelemetry.serviceMonitor.enabled=true' \
    . || echo "---") | tee /dev/stderr |
    yq 'length > 0' | tee /dev/stderr)
  [ "${actual}" = "true" ]
}

@test "prometheus/ServiceMonitor-server: assertScrapeTimeout default" {
  cd `chart_dir`
  local actual=$( (helm template \
    --show-only templates/prometheus-servicemonitor.yaml \
    --set 'serverTelemetry.serviceMonitor.enabled=true' \
    .) | tee /dev/stderr |
    yq -r '.spec.endpoints[0].scrapeTimeout' | tee /dev/stderr)
  [ "${actual}" = "10s" ]
}

@test "prometheus/ServiceMonitor-server: assertScrapeTimeout update" {
  cd `chart_dir`
  local actual=$( (helm template \
    --show-only templates/prometheus-servicemonitor.yaml \
    --set 'serverTelemetry.serviceMonitor.enabled=true' \
    --set 'serverTelemetry.serviceMonitor.scrapeTimeout=60s' \
    .) | tee /dev/stderr |
    yq -r '.spec.endpoints[0].scrapeTimeout' | tee /dev/stderr)
  [ "${actual}" = "60s" ]
}

@test "prometheus/ServiceMonitor-server: assertInterval default" {
  cd `chart_dir`
  local actual=$( (helm template \
    --show-only templates/prometheus-servicemonitor.yaml \
    --set 'serverTelemetry.serviceMonitor.enabled=true' \
    .) | tee /dev/stderr |
    yq -r '.spec.endpoints[0].interval' | tee /dev/stderr)
  [ "${actual}" = "30s" ]
}

@test "prometheus/ServiceMonitor-server: assertInterval update" {
  cd `chart_dir`
  local output=$( (helm template \
    --show-only templates/prometheus-servicemonitor.yaml \
    --set 'serverTelemetry.serviceMonitor.enabled=true' \
    --set 'serverTelemetry.serviceMonitor.interval=60s' \
    .) | tee /dev/stderr)

  [ "$(echo "$output" | yq -r '.spec.endpoints[0].interval')" = "60s" ]
}

@test "prometheus/ServiceMonitor-server: assertSelectors default" {
  cd `chart_dir`
  local output=$( (helm template \
    --show-only templates/prometheus-servicemonitor.yaml \
    --set 'serverTelemetry.serviceMonitor.enabled=true' \
    .) | tee /dev/stderr)

  [ "$(echo "$output" | yq -r '.metadata.labels | length')" = "5" ]
  [ "$(echo "$output" | yq -r '.metadata.labels.release')" = "prometheus" ]
}

@test "prometheus/ServiceMonitor-server: assertSelectors override" {
  cd `chart_dir`
  local output=$( (helm template \
    --show-only templates/prometheus-servicemonitor.yaml \
    --set 'serverTelemetry.serviceMonitor.enabled=true' \
    --set 'serverTelemetry.serviceMonitor.selectors.baz=qux' \
    --set 'serverTelemetry.serviceMonitor.selectors.bar=foo' \
    .) | tee /dev/stderr)

  [ "$(echo "$output" | yq -r '.metadata.labels | length')" = "6" ]
  [ "$(echo "$output" | yq -r '.metadata.labels | has("app")')" = "false" ]
  [ "$(echo "$output" | yq -r '.metadata.labels.baz')" = "qux" ]
  [ "$(echo "$output" | yq -r '.metadata.labels.bar')" = "foo" ]
}

@test "prometheus/ServiceMonitor-server: assertEndpoints noTLS" {
  cd `chart_dir`
  local output=$( (helm template \
    --show-only templates/prometheus-servicemonitor.yaml \
    --set 'global.tlsDisable=true' \
    --set 'serverTelemetry.serviceMonitor.enabled=true' \
    .) | tee /dev/stderr)

  [ "$(echo "$output" | yq -r '.spec.endpoints | length')" = "1" ]
  [ "$(echo "$output" | yq -r '.spec.endpoints[0].port')" = "http" ]
  [ "$(echo "$output" | yq -r '.spec.endpoints[0].scheme')" = "http" ]
}

@test "prometheus/ServiceMonitor-server: assertEndpoints TLS" {
  cd `chart_dir`
  local output=$( (helm template \
    --show-only templates/prometheus-servicemonitor.yaml \
    --set 'global.tlsDisable=false' \
    --set 'serverTelemetry.serviceMonitor.enabled=true' \
    .) | tee /dev/stderr)

  [ "$(echo "$output" | yq -r '.spec.endpoints | length')" = "1" ]
  [ "$(echo "$output" | yq -r '.spec.endpoints[0].port')" = "https" ]
  [ "$(echo "$output" | yq -r '.spec.endpoints[0].scheme')" = "https" ]
}

@test "prometheus/ServiceMonitor-server: assertEndpointsPort update" {
  cd `chart_dir`
  local output=$( (helm template \
    --show-only templates/prometheus-servicemonitor.yaml \
    --set 'serverTelemetry.serviceMonitor.enabled=true' \
    --set 'serverTelemetry.serviceMonitor.port=metrics-tls' \
    .) | tee /dev/stderr)

  [ "$(echo "$output" | yq -r '.spec.endpoints[0].port')" = "metrics-tls" ]
}

@test "prometheus/ServiceMonitor-server: assertEndpointsScheme update" {
  cd `chart_dir`
  local output=$( (helm template \
    --show-only templates/prometheus-servicemonitor.yaml \
    --set 'serverTelemetry.serviceMonitor.enabled=true' \
    --set 'global.tlsDisable=false' \
    --set 'serverTelemetry.serviceMonitor.scheme=http' \
    .) | tee /dev/stderr)

  [ "$(echo "$output" | yq -r '.spec.endpoints[0].port')" = "https" ]
  [ "$(echo "$output" | yq -r '.spec.endpoints[0].scheme')" = "http" ]
}

@test "prometheus/ServiceMonitor-server: tlsConfig default" {
  cd `chart_dir`
  local output=$( (helm template \
    --show-only templates/prometheus-servicemonitor.yaml \
    --set 'serverTelemetry.serviceMonitor.enabled=true' \
    .) | tee /dev/stderr)

  [ "$(echo "$output" | yq -r '.spec.endpoints[0].tlsConfig.insecureSkipVerify')" = "true" ]
}

@test "prometheus/ServiceMonitor-server: tlsConfig override" {
  cd `chart_dir`
  local output=$( (helm template \
    --show-only templates/prometheus-servicemonitor.yaml \
    --set 'serverTelemetry.serviceMonitor.tlsConfig.ca=ca.crt' \
    --set 'serverTelemetry.serviceMonitor.enabled=true' \
    .) | tee /dev/stderr)

  [ "$(echo "$output" | yq -r '.spec.endpoints[0].tlsConfig.ca')" = "ca.crt" ]
}

@test "prometheus/ServiceMonitor-server: authorization default" {
  cd `chart_dir`
  local output=$( (helm template \
    --show-only templates/prometheus-servicemonitor.yaml \
    --set 'serverTelemetry.serviceMonitor.enabled=true' \
    .) | tee /dev/stderr)

  [ "$(echo "$output" | yq -r '.spec.endpoints[0] | has("bearerTokenFile")')" = "false" ]
}

@test "prometheus/ServiceMonitor-server: authorization set" {
  cd `chart_dir`
  local output=$( (helm template \
    --show-only templates/prometheus-servicemonitor.yaml \
    --set 'serverTelemetry.serviceMonitor.enabled=true' \
    --set 'serverTelemetry.serviceMonitor.authorization.credentials.key=secretkey' \
    --set 'serverTelemetry.serviceMonitor.authorization.credentials.name=secretname' \
    .) | tee /dev/stderr)

  [ "$(echo "$output" | yq -r '.spec.endpoints[0].authorization.credentials.key')" = "secretkey" ]
  [ "$(echo "$output" | yq -r '.spec.endpoints[0].authorization.credentials.name')" = "secretname" ]
}

@test "prometheus/ServiceMonitor-server: bearerTokenFile set" {
  cd `chart_dir`
  local output=$( (helm template \
    --show-only templates/prometheus-servicemonitor.yaml \
    --set 'serverTelemetry.serviceMonitor.enabled=true' \
    --set 'serverTelemetry.serviceMonitor.bearerTokenFile=secureToken' \
    .) | tee /dev/stderr)

  [ "$(echo "$output" | yq -r '.spec.endpoints[0].bearerTokenFile')" = "secureToken" ]
}

@test "prometheus/ServiceMonitor-server: scrapeClass set" {
  cd `chart_dir`
  local output=$( (helm template \
    --show-only templates/prometheus-servicemonitor.yaml \
    --set 'serverTelemetry.serviceMonitor.enabled=true' \
    --set 'serverTelemetry.serviceMonitor.scrapeClass=foo' \
    .) | tee /dev/stderr)

  [ "$(echo "$output" | yq -r '.spec.scrapeClass')" = "foo" ]
}

{{- if and .Values.snapshotAgent.enabled .Values.snapshotAgent.serviceAccount.create -}}
apiVersion: v1
kind: ServiceAccount
metadata:
  name: {{ template "openbao.snapshotAgent.serviceAccount.name" . }}
  namespace: {{ include "openbao.namespace" . }}
  labels:
    helm.sh/chart: {{ include "openbao.chart" . }}
    app.kubernetes.io/name: {{ include "openbao.name" . }}
    app.kubernetes.io/instance: {{ .Release.Name }}
    app.kubernetes.io/managed-by: {{ .Release.Service }}
    {{- if  .Values.snapshotAgent.serviceAccount.extraLabels -}}
      {{- toYaml .Values.snapshotAgent.serviceAccount.extraLabels | nindent 4 -}}
    {{- end -}}
  {{ template "openbao.snapshotAgent.serviceAccount.annotations" . }}
{{ end }}

{{/*
Copyright (c) HashiCorp, Inc.
SPDX-License-Identifier: MPL-2.0
*/}}

{{- template "openbao.csiEnabled" . -}}
{{- if and (.csiEnabled) (eq (.Values.csi.agent.enabled | toString) "true") -}}
apiVersion: v1
kind: ConfigMap
metadata:
  name: {{ template "openbao.fullname" . }}-csi-provider-agent-config
  namespace: {{ include "openbao.namespace" . }}
  labels:
    helm.sh/chart: {{ include "openbao.chart" . }}
    app.kubernetes.io/name: {{ include "openbao.name" . }}-csi-provider
    app.kubernetes.io/instance: {{ .Release.Name }}
    app.kubernetes.io/managed-by: {{ .Release.Service }}
data:
  config.hcl: |
    vault {
        {{- if include "openbao.global.externalAddr" . }}
        "address" = "{{ include "openbao.global.externalAddr" . }}"
        {{- else }}
        "address" = "{{ include "openbao.scheme" . }}://{{ template "openbao.fullname" . }}.{{ include "openbao.namespace" . }}.svc:{{ .Values.server.service.port }}"
        {{- end }}
    }

    cache {}

    listener "unix" {
        address = "/var/run/vault/agent.sock"
        tls_disable = true
    }
{{- end }}

---
{{- if .Values.snapshotAgent.enabled }}
apiVersion: v1
kind: ConfigMap
metadata:
  name: {{ template "openbao.fullname" . }}-snapshot
  namespace: {{ include "openbao.namespace" . }}
  labels:
    helm.sh/chart: {{ include "openbao.chart" . }}
    app.kubernetes.io/name: {{ include "openbao.name" . }}
    app.kubernetes.io/instance: {{ .Release.Name }}
    app.kubernetes.io/managed-by: {{ .Release.Service }}
data:
  S3_HOST: {{ .Values.snapshotAgent.config.s3Host }}
  S3_BUCKET: {{ .Values.snapshotAgent.config.s3Bucket }}
  {{- if .Values.snapshotAgent.config.s3cmdExtraFlag }}
  S3CMD_EXTRA_FLAG: {{ .Values.snapshotAgent.config.s3cmdExtraFlag }}
  {{- end }}
  S3_URI: {{ .Values.snapshotAgent.config.s3Uri }}
  S3_EXPIRE_DAYS: {{ .Values.snapshotAgent.config.s3ExpireDays | quote }}
  BAO_AUTH_PATH: {{ .Values.snapshotAgent.config.baoAuthPath }}
  {{- if .Values.snapshotAgent.config.baoNamespace }}
  BAO_NAMESPACE: {{ .Values.snapshotAgent.config.baoNamespace }}
  {{- end }}
  {{- if .Values.snapshotAgent.config.baoAuthNamespace }}
  BAO_AUTH_NAMESPACE: {{ .Values.snapshotAgent.config.baoAuthNamespace }}
  {{- end }}
  {{- if .Values.snapshotAgent.config.baoSecretPath }}
  BAO_SECRET_PATH: {{ .Values.snapshotAgent.config.baoSecretPath }}
  {{- end }}
  {{- if .Values.snapshotAgent.config.tokenPath }}
  TOKEN_PATH: {{ .Values.snapshotAgent.config.tokenPath }}
  {{- end }}
  BAO_ROLE: {{ .Values.snapshotAgent.config.baoRole }}
  {{- if include "openbao.global.externalAddr" . }}
  BAO_ADDR: "{{ include "openbao.global.externalAddr" . }}"
  {{- else if and (eq .mode "ha") (eq (.Values.server.service.active.enabled | toString) "true")}}
  BAO_ADDR: {{ include "openbao.scheme" . }}://{{ template "openbao.fullname" . }}-active.{{ include "openbao.namespace" . }}.svc:{{ .Values.server.service.port }}
  {{- else }}
  BAO_ADDR: {{ include "openbao.scheme" . }}://{{ template "openbao.fullname" . }}.{{ include "openbao.namespace" . }}.svc:{{ .Values.server.service.port }}
  {{- end }}
{{ end }}
